<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../stores/auth';const username=ref('buyer'),password=ref('Demo@2026'),busy=ref(false),error=ref(''),router=useRouter(),auth=useAuthStore();async function login(){busy.value=true;error.value='';try{const user=await auth.login(username.value,password.value);router.push(user.role==='SUPPLIER'?'/portal':'/admin')}catch(e){error.value=e.response?.data?.message||'登录失败，请检查账号'}finally{busy.value=false}}function choose(type){username.value=type;password.value='Demo@2026';login()}</script>
<template><div class="login"><div class="login-story"><div class="brand light"><div class="brand-mark">ZH</div><div><b>知华 SRM</b><small>ZHUATECH SUPPLIER RELATIONSHIP MANAGEMENT</small></div></div><div class="story-copy"><span>连接采购与供应</span><h1>每一次询价、交付与整改<br/>都有清晰的业务依据。</h1><p>面向成长型制造企业的供应商全生命周期协同平台。</p></div><div class="story-stats"><div><b>128</b><span>合作供应商</span></div><div><b>96.4%</b><span>订单准交率</span></div><div><b>7</b><span>进行中寻源</span></div></div><small class="copyright">© 2026 上海如静知华信息科技有限公司</small></div><div class="login-panel"><div class="login-box"><span class="eyebrow">WELCOME BACK</span><h2>登录业务工作台</h2><p>选择角色进入对应的演示工作区</p><label>账号</label><input v-model="username" autocomplete="username"/><label>密码</label><input v-model="password" type="password" autocomplete="current-password" @keyup.enter="login"/><div class="login-options"><label><input type="checkbox" checked/> 记住账号</label><a href="https://www.zhuatech.cn/" target="_blank">获取部署支持</a></div><button class="primary full" @click="login" :disabled="busy">{{busy?'正在登录…':'登录'}}</button><span class="login-error">{{error}}</span><div class="demo-select"><span>快捷体验</span><button @click="choose('buyer')">采购管理端</button><button @click="choose('supplier')">供应商门户</button></div><small class="demo-note">演示账号：buyer / supplier　密码：Demo@2026</small></div></div></div></template>
